import { column } from "./values.js";
export const OPERATIONS_TABLE = {
    table: "operations",
    aggregate: "operation",
    keyColumns: ["id"],
    columns: [
        column("id", "text"),
        column("kind", "text"),
        column("status", "text"),
        column("origin", "text"),
        column("createdBy", "text"),
        column("createdAt", "bigint"),
        column("startedAt", "bigint", { nullAs: "null" }),
        column("firstStartedAt", "bigint"),
        column("lastResumedAt", "bigint"),
        column("queuedAt", "bigint"),
        column("completedAt", "bigint", { nullAs: "null" }),
        column("lastProgressAt", "bigint"),
        column("nextAttemptAt", "bigint"),
        column("waitingOn", "text"),
        column("attempts", "integer"),
        column("resumeCount", "integer"),
        column("error", "text"),
        column("rolledBack", "boolean"),
        column("input", "jsonb"),
        column("steps", "jsonb"),
        column("attemptHistory", "jsonb"),
        column("output", "jsonb"),
        column("progress", "jsonb"),
        column("gatewayId", "text"),
        column("inputUid", "text"),
        column("userMigrationV2", "jsonb", { column: "user_migration_v2" }),
        column("sourceTransferExecution", "jsonb"),
        column("schedulerHandoff", "jsonb"),
        column("schedulerHandoffReleased", "boolean"),
        column("schedulerHandoffReleasedAt", "bigint"),
        column("schedulerHandoffLost", "text"),
        column("cutoverCommittedAt", "bigint"),
        column("cancellationRequestedAt", "bigint"),
        column("cancelledByDeletionId", "text"),
        column("retryRequestedAt", "bigint"),
        column("retryRequestedBy", "text"),
        column("supersededBy", "jsonb"),
        column("restoreAttempt", "jsonb"),
        column("restoreRuntimeRecovery", "jsonb"),
        column("sourceRuntimeRecovery", "jsonb"),
        column("sourceRecoverySupersededBy", "text"),
        column("sourceRecoveryRequestedAt", "bigint"),
        column("sourceRecoveryRequestedBy", "text"),
        column("nativeReturnSourceRecoveryReceipts", "jsonb"),
        column("forceDrainRequest", "jsonb"),
        column("rolloutLane", "text"),
        column("expireAt", "bigint"),
    ],
    immutableFields: ["id", "kind", "createdAt", "createdBy"],
};
export const OPERATION_AUDITS_TABLE = {
    table: "operation_audits",
    aggregate: "operation-audit",
    keyColumns: ["id"],
    constants: { recordType: "audit" },
    columns: [
        column("id", "text"),
        column("schemaVersion", "integer"),
        column("status", "text"),
        column("lifecycleStage", "text"),
        column("idempotencyKey", "text"),
        column("mutationFingerprint", "text"),
        column("mutation", "jsonb"),
        column("actor", "text"),
        column("forced", "boolean"),
        column("what", "text"),
        column("why", "text"),
        column("target", "jsonb"),
        column("preActionStatus", "jsonb"),
        column("aliasPlan", "jsonb"),
        column("aliasOutcomes", "jsonb"),
        column("releaseRollout", "jsonb"),
        column("testProvenance", "jsonb"),
        column("outcome", "text"),
        column("partialOutcome", "jsonb"),
        column("createdAt", "bigint"),
        column("actionClaimId", "text"),
        column("actionStartedAt", "bigint"),
        column("actionRecoveryCount", "integer"),
        column("completedAt", "bigint", { nullAs: "null" }),
        column("error", "text"),
        column("expireAt", "bigint"),
    ],
    immutableFields: ["id", "recordType", "schemaVersion", "idempotencyKey", "mutationFingerprint", "createdAt"],
};
export const GATEWAY_RECOVERY_RECEIPTS_TABLE = {
    table: "gateway_recovery_receipts",
    aggregate: "gateway-recovery-receipt",
    keyColumns: ["id"],
    columns: [
        column("id", "text"),
        column("kind", "text"),
        column("status", "text"),
        column("origin", "text"),
        column("createdBy", "text"),
        column("createdAt", "bigint"),
        column("startedAt", "bigint", { nullAs: "null" }),
        column("firstStartedAt", "bigint"),
        column("completedAt", "bigint", { nullAs: "null" }),
        column("input", "jsonb"),
        column("steps", "jsonb"),
        column("gatewayId", "text"),
        column("inputUid", "text"),
        column("recoveryReceipt", "jsonb"),
    ],
    immutableFields: ["id", "kind", "createdAt", "createdBy"],
};
